// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;

    function setUp() public {
        c = new X_WALLET(address(new Log()));
    }

    function testFuzz_property(uint256 amount, address actor, uint256 warpTo, uint256 collectTime) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        amount = bound(amount, 2 ether, 100 ether);
        warpTo = bound(warpTo, 1, 1_000_000_000);
        collectTime = bound(collectTime, 1, type(uint128).max);

        vm.warp(warpTo);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(collectTime);

        // General rule: after Put(_t), the account's unlockTime recorded in the log
        // history reflects that collection is only allowed strictly after the stored
        // unlock time; in particular if the caller now Collects, it must fail whenever
        // block.timestamp is not strictly greater than the unlockTime P stored
        // (i.e. max(_t, now)).
        if (collectTime >= warpTo) {
            // unlockTime stored == collectTime; collecting now must fail (timestamp not > unlockTime)
            vm.prank(actor);
            c.Collect(amount);
            assertEq(address(c).balance, amount, "funds must not be collectable before unlockTime");
        } else {
            // unlockTime stored == warpTo (block.timestamp); collecting immediately must fail
            vm.prank(actor);
            c.Collect(amount);
            assertEq(address(c).balance, amount, "funds must not be collectable at unlockTime");
        }
    }
}
